# Géolocalisation asynchrone et mise en cache : aucune page n'attend un service distant.
geo_cache: dict[str, dict[str, Any]] = {}
geo_pending: set[str] = set()
geo_lock = threading.RLock()
geo_executor = ThreadPoolExecutor(max_workers=2, thread_name_prefix="RoR-GeoIP")


# ============================================================================
# UTILITAIRES
# ============================================================================


def now() -> str:
    return datetime.now().strftime("%Y-%m-%d %H:%M:%S")


def safe_read(path: Path, default: str = "") -> str:
    try:
        return path.read_text(encoding="utf-8", errors="replace")
    except Exception:
        return default


def safe_write(path: Path, text: str) -> bool:
    try:
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(text, encoding="utf-8")
        return True
    except Exception:
        return False


def clean(value: Any, limit: int = 1000) -> str:
    text = str(value if value is not None else "")
    text = text.replace("\x00", " ").replace("\r", " ").replace("\n", " ")
    text = re.sub(r"\s+", " ", text).strip()
    return text[:limit]


def esc(value: Any) -> str:
    return html.escape(str(value if value is not None else ""), quote=True)


def js_json(value: Any) -> str:
    return (
        json.dumps(value, ensure_ascii=False, separators=(",", ":"))
        .replace("<", "\\u003c")
        .replace(">", "\\u003e")
        .replace("&", "\\u0026")
    )


def normalize_token(value: Any) -> str:
    return re.sub(r"[^A-Za-z0-9@._:-]", "", str(value or ""))


def valid_uid(value: Any) -> bool:
    return bool(re.fullmatch(r"\d{1,12}", str(value).strip()))


def parse_api_id(value: Any) -> int | None:
    if isinstance(value, bool) or not re.fullmatch(r"\d{1,12}", str(value).strip()):
        return None
    return int(value)


def human_bytes(value: Any) -> str:
    try:
        size = float(value or 0)
    except Exception:
        size = 0.0
    for unit in ("B", "KB", "MB", "GB", "TB"):
        if size < 1024 or unit == "TB":
            return f"{size:.1f} {unit}"
        size /= 1024
    return f"{size:.1f} TB"


def uptime_text(seconds: int) -> str:
    seconds = max(0, int(seconds or 0))
    hours, rem = divmod(seconds, 3600)
    minutes, secs = divmod(rem, 60)
    return f"{hours:02d}:{minutes:02d}:{secs:02d}"


def local_ip() -> str:
    sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    try:
        sock.connect(("8.8.8.8", 80))
        return sock.getsockname()[0]
    except Exception:
        return "127.0.0.1"
    finally:
        sock.close()


# ============================================================================
# FICHIERS ROR
# ============================================================================


class Paths:
    def __init__(self, root: Path):
        self.root = root

    @property
    def cfg(self) -> Path:
        return self.root / "server.cfg"

    @property
    def log(self) -> Path:
        return self.root / "server.log"

    @property
    def motd(self) -> Path:
        return self.root / "server.motd"

    @property
    def rules(self) -> Path:
        return self.root / "server.rules"

    @property
    def auth(self) -> Path:
        return self.root / "server.auth"

    @property
    def resources(self) -> Path:
        return self.root / "resources"

    @property
    def backups(self) -> Path:
        return self.root / "backups"


paths = Paths(SERVER_ROOT)


def cfg_value(key: str, default: str = "") -> str:
    text = safe_read(paths.cfg)
    pattern = re.compile(rf"^\s*{re.escape(key)}\s*=\s*(.*?)\s*$", re.I | re.M)
    match = pattern.search(text)
    if not match:
        return default
    return match.group(1).strip()


def configured_game_port() -> int:
    raw = cfg_value("port", "")
    try:
        return int(raw)
    except Exception:
        return ROR_GAME_PORT_DEFAULT


def runtime_paths() -> dict[str, Path]:
    defaults = {
        "log": paths.log,
        "motd": paths.motd,
        "rules": paths.rules,
        "auth": paths.auth,
        "resources": paths.resources,
    }
    keys = {
        "log": "logfilename",
        "motd": "motdfile",
        "rules": "rulesfile",
        "auth": "authfile",
        "resources": "resdir",
    }
    result: dict[str, Path] = {}
    for name, default in defaults.items():
        raw = cfg_value(keys[name], "")
        if not raw:
            result[name] = default
            continue
        candidate = Path(os.path.expandvars(os.path.expanduser(raw)))
        if not candidate.is_absolute():
            candidate = SERVER_ROOT / candidate
        try:
            result[name] = candidate.resolve()
        except Exception:
            result[name] = candidate
    return result


MAP_FILE_EXTENSIONS = {".terrn", ".terrn2"}
MAP_PREVIEW_EXTENSIONS = {".jpg", ".jpeg", ".png", ".webp", ".gif"}


def map_path_under(root: Path, relative_value: str) -> Path | None:
    value = Path(str(relative_value).replace("\\", "/"))
    if not relative_value or value.is_absolute():
        return None
    resolved_root = root.resolve()
    resolved_path = (resolved_root / value).resolve()
    try:
        resolved_path.relative_to(resolved_root)
    except ValueError:
        return None
    return resolved_path


def discover_maps() -> list[dict[str, str]]:
    resource_root = runtime_paths()["resources"].resolve()
    manifest_path = APP_DIR / "maps.json"
    if manifest_path.is_file():
        try:
            manifest = json.loads(safe_read(manifest_path))
            manifest_maps = manifest.get("maps", []) if isinstance(manifest, dict) else []
            if not isinstance(manifest_maps, list):
                return []
        except (json.JSONDecodeError, OSError):
            return []

        asset_roots = list(dict.fromkeys((resource_root, APP_DIR.resolve())))
        listed_maps: list[dict[str, str]] = []
        for entry in manifest_maps:
            if not isinstance(entry, dict):
                continue
            terrain_value = clean(entry.get("terrain_file", ""), 500)
            if not terrain_value:
                continue
            terrain_file = None
            asset_root = None
            for candidate_root in asset_roots:
                candidate = map_path_under(candidate_root, terrain_value)
                if candidate and candidate.is_file() and candidate.suffix.lower() in MAP_FILE_EXTENSIONS:
                    terrain_file = candidate
                    asset_root = candidate_root
                    break
            if terrain_file is None or asset_root is None:
                continue

            preview_path = ""
            preview_value = clean(entry.get("preview", ""), 500)
            if preview_value:
                preview_file = map_path_under(asset_root, preview_value)
                if preview_file and preview_file.is_file() and preview_file.suffix.lower() in MAP_PREVIEW_EXTENSIONS:
                    preview_path = preview_value.replace("\\", "/")

            config_value = clean(entry.get("config_value", terrain_file.stem), 120)
            if not config_value:
                continue
            config_resdir = ""
            if asset_root != resource_root:
                config_resdir = os.path.relpath(asset_root, SERVER_ROOT).replace("\\", "/") or "."
            listed_maps.append(
                {
                    "id": terrain_value.replace("\\", "/"),
                    "name": clean(entry.get("name", terrain_file.stem), 100),
                    "config_value": config_value,
                    "path": terrain_value.replace("\\", "/"),
                    "preview": preview_path,
                    "_asset_root": str(asset_root),
                    "_config_resdir": config_resdir,
                }
            )
        return listed_maps

    if not resource_root.is_dir():
        return []

    maps: list[dict[str, str]] = []
    try:
        terrain_files = sorted(
            (path for path in resource_root.rglob("*") if path.is_file() and path.suffix.lower() in MAP_FILE_EXTENSIONS),
            key=lambda path: str(path).lower(),
        )
    except OSError:
        return []

    for terrain_file in terrain_files:
        relative_path = terrain_file.relative_to(resource_root).as_posix()
        preview_path = ""
        try:
            previews = [
                path for path in terrain_file.parent.iterdir()
                if path.is_file() and path.suffix.lower() in MAP_PREVIEW_EXTENSIONS
            ]
            preferred_stems = {terrain_file.stem.lower(), "preview", "thumbnail", "cover"}
            previews = [path for path in previews if path.stem.lower() in preferred_stems]
            previews.sort(key=lambda path: (path.stem.lower() not in preferred_stems, path.name.lower()))
            if previews:
                preview_path = previews[0].relative_to(resource_root).as_posix()
        except OSError:
            pass

        maps.append(
            {
                "id": relative_path,
                "name": terrain_file.stem.replace("_", " ").replace("-", " "),
                "config_value": terrain_file.stem,
                "path": relative_path,
                "preview": preview_path,
                "_asset_root": str(resource_root),
                "_config_resdir": "",
            }
        )
    return maps


def backup_file(path: Path) -> Path | None:
    if not path.exists():
        return None
    stamp = datetime.now().strftime("%Y%m%d_%H%M%S_%f")
    destination = paths.backups / stamp / path.name
    try:
        destination.parent.mkdir(parents=True, exist_ok=True)
        destination.write_bytes(path.read_bytes())
        return destination
    except Exception as exc:
        emit_event("ERROR", f"Backup impossible : {exc}")
        return None


# ============================================================================
# EVENTS
# ============================================================================

events: list[dict[str, Any]] = []
event_subscribers: list[queue.Queue] = []
events_lock = threading.RLock()


def emit_event(kind: str, message: str, data: dict[str, Any] | None = None) -> None:
    item = {
        "time": now(),
        "kind": clean(kind, 40),
        "message": clean(message, 2000),
        "data": data or {},
    }
    with events_lock:
        events.append(item)
        if len(events) > MAX_EVENTS:
            del events[:-MAX_EVENTS]
        for subscriber in list(event_subscribers):
            try:
                subscriber.put_nowait(item)
            except queue.Full:
                try:
                    subscriber.get_nowait()
                    subscriber.put_nowait(item)
                except Exception:
                    pass
            except Exception:
                try:
                    event_subscribers.remove(subscriber)
                except ValueError:
                    pass


# ============================================================================
# API C++ ROR — COUCHE ROBUSTE
# ============================================================================

# A single lock prevents concurrent HTTP requests from the multithreaded Flask
# server from hitting the native RoR API at the exact same instant. In
# particular, a player list/status poll cannot race the kick/ban operation.
ror_api_lock = threading.RLock()


def _result_success(data: Any) -> bool:
    if isinstance(data, list):
        return True
    if not isinstance(data, dict):
        return False
    if "success" in data:
        return bool(data.get("success"))
    if "ok" in data:
        return bool(data.get("ok"))
    if "error" in data:
        return False
    return True


def _result_message(data: Any, default: str = "Action effectuée.") -> str:
    if isinstance(data, dict):
        for key in ("message", "msg", "detail", "error"):
            value = data.get(key)
            if value:
                return clean(value, 2000)
    if isinstance(data, str) and data.strip():
        return clean(data, 2000)
    return default


def call_ror_api(
    endpoint: str,
    payload: dict[str, Any] | None = None,
    method: str | None = None,
    *,
    allow_empty_success: bool = False,
) -> dict[str, Any] | list[Any]:
    """Call the native RoR API and always return a structured result.

    Important properties:
    - no global requests.Session shared between Flask threads;
    - finite timeout on every request;
    - POST operations are never retried automatically;
    - empty 2xx POST responses can still be treated as success;
    - transport failures are distinguishable from an invalid user request;
    - HTTP status is kept internally as _http_status.
    """
    endpoint = "/" + str(endpoint).lstrip("/")
    url = ROR_API_URL + endpoint
    http_method = (method or ("POST" if payload is not None else "GET")).upper()

    if http_method not in {"GET", "POST"}:
        return {
            "success": False,
            "error": f"Méthode HTTP non supportée : {http_method}",
            "_http_status": 400,
            "_transport_error": False,
        }

    headers = {
        "User-Agent": f"{APP_NAME}/{APP_VERSION}",
        "Accept": "application/json, text/plain;q=0.9, */*;q=0.8",
    }

    try:
        with ror_api_lock:
            response = requests.request(
                method=http_method,
                url=url,
                json=payload if http_method == "POST" else None,
                headers=headers,
                timeout=(1.5, ROR_API_TIMEOUT),
            )

        status = int(response.status_code)
        content_type = (response.headers.get("Content-Type") or "").lower()
        body_text = response.text.strip()

        parsed: Any = None
        if body_text:
            try:
                parsed = response.json()
            except ValueError:
                parsed = None

        if 200 <= status < 300:
            if isinstance(parsed, (dict, list)):
                if isinstance(parsed, dict):
                    parsed.setdefault("success", _result_success(parsed))
                    parsed["_http_status"] = status
                    parsed["_transport_error"] = False
                return parsed

            if allow_empty_success or http_method == "POST":
                return {
                    "success": True,
                    "message": body_text or "Action effectuée.",
                    "_http_status": status,
                    "_transport_error": False,
                }

            return {
                "success": False,
                "error": "Réponse vide de l'API RoR.",
                "_http_status": status,
                "_transport_error": False,
            }

        # HTTP error: preserve RoR's JSON error when available.
        if isinstance(parsed, dict):
            parsed["success"] = False
            parsed["_http_status"] = status
            parsed["_transport_error"] = False
            if not parsed.get("error"):
                parsed["error"] = f"API RoR HTTP {status}."
            return parsed

        # Never expose a huge HTML/proxy page in the UI/logs.
        detail = clean(body_text, 1000)
        if not detail:
            detail = f"API RoR HTTP {status}."
        elif len(detail) > 0:
            detail = f"API RoR HTTP {status} : {detail}"

        return {
            "success": False,
            "error": detail,
            "_http_status": status,
            "_transport_error": False,
        }

    except requests.exceptions.ConnectTimeout:
        return {
            "success": False,
            "error": f"Connexion API RoR impossible (timeout) : {ROR_API_URL}",
            "_http_status": 504,
            "_transport_error": True,
        }
    except requests.exceptions.ReadTimeout:
        return {
            "success": False,
            "error": f"API RoR trop lente (timeout {ROR_API_TIMEOUT:.1f}s).",
            "_http_status": 504,
            "_transport_error": True,
        }
    except requests.exceptions.ConnectionError:
        return {
            "success": False,
            "error": f"API RoR inaccessible : {ROR_API_URL}",
            "_http_status": 502,
            "_transport_error": True,
        }
    except requests.exceptions.RequestException as exc:
        return {
            "success": False,
            "error": f"Erreur réseau API RoR : {clean(exc, 500)}",
            "_http_status": 502,
            "_transport_error": True,
        }
    except Exception as exc:
        return {
            "success": False,
            "error": f"Erreur API : {clean(exc, 500)}",
            "_http_status": 500,
            "_transport_error": False,
        }


def call_ror_admin_api(endpoint: str, payload: dict[str, Any]) -> dict[str, Any] | list[Any]:
    if not ROR_API_TOKEN:
        return {
            "success": False,
            "error": "Jeton d'administration absent. Définis ROR_ADMIN_TOKEN dans l'environnement du panneau.",
            "_http_status": 503,
            "_transport_error": False,
        }
    return call_ror_api(
        endpoint,
        {"token": ROR_API_TOKEN, **payload},
        "POST",
        allow_empty_success=True,
    )


def upstream_error_status(result: Any) -> int:
    if not isinstance(result, dict):
        return 502
    status = int(result.get("_http_status", 502))
    if result.get("_transport_error"):
        return 504 if status == 504 else 502
    return status if status in (400, 401, 403, 404, 409, 422, 429, 503) else 502


def api_client_count(status: Any) -> int:
    if isinstance(status, list):
        return len(status)
    if not isinstance(status, dict):
        return 0
    for key in ("clients", "players", "count"):
        value = status.get(key)
        if isinstance(value, list):
            return len(value)
        try:
            if value is not None:
                return max(0, int(value))
        except Exception:
            continue
    return 0


def api_players_data() -> tuple[list[dict[str, Any]], str, int]:
    result = call_ror_api("/api/v1/players")
    status = int(result.get("_http_status", 200)) if isinstance(result, dict) else 200

    if isinstance(result, dict) and not _result_success(result) and result.get("error"):
        return [], str(result.get("error")), status

    raw_players: Any
    if isinstance(result, list):
        raw_players = result
    elif isinstance(result, dict):
        raw_players = result.get("players", result.get("data", []))
        if isinstance(raw_players, dict):
            raw_players = raw_players.get("players", [])
        if not isinstance(raw_players, list):
            return [], "Réponse API valide, mais la liste des joueurs n'a pas pu être lue.", status
    else:
        return [], "Format de réponse non supporté par l'API.", status

    normalized: list[dict[str, Any]] = []
    for player in raw_players:
        if not isinstance(player, dict):
            continue
        player_id = player.get("id", player.get("player_id", player.get("uid", "")))
        auth = player.get("auth", player.get("role", "user"))
        streams = player.get("streams", 0)
        try:
            streams = int(streams)
        except Exception:
            streams = 0
        normalized.append(
            {
                "id": player_id,
                "name": clean(player.get("name", ""), 100),
                "ip": clean(player.get("ip", ""), 120),
                "auth": clean(auth or "user", 40),
                "streams": max(0, streams),
                "raw": player,
            }
        )

    normalized.sort(key=lambda p: (p["name"] or "").lower())
    return normalized, "", status


def api_bans_data() -> tuple[list[dict[str, Any]], str, int]:
    result = call_ror_api("/api/v1/bans")
    status = int(result.get("_http_status", 200)) if isinstance(result, dict) else 200

    if isinstance(result, dict) and not _result_success(result) and result.get("error"):
        return [], str(result.get("error")), status

    raw_bans: Any
    if isinstance(result, list):
        raw_bans = result
    elif isinstance(result, dict):
        raw_bans = result.get("bans", result.get("data", result.get("entries", [])))
        if isinstance(raw_bans, dict):
            nested_bans = raw_bans.get("bans", raw_bans.get("entries"))
            raw_bans = nested_bans if nested_bans is not None else ([raw_bans] if "ban_id" in raw_bans or "id" in raw_bans else [])
        if not raw_bans and ("ban_id" in result or "id" in result):
            raw_bans = [result]
        if not isinstance(raw_bans, list):
            return [], "Réponse API valide, mais la liste des bannissements n'a pas pu être lue.", status
    else:
        return [], "Format de réponse non supporté par l'API.", status

    normalized: list[dict[str, Any]] = []
    for ban in raw_bans:
        if not isinstance(ban, dict):
            continue
        normalized.append(
            {
                "id": ban.get("ban_id", ban.get("id", "")),
                "player_id": ban.get("player_id", ban.get("uid", ban.get("player_uid", ""))),
                "name": clean(ban.get("name", ban.get("player_name", ban.get("nickname", ""))), 100),
                "ip": clean(ban.get("ip", ""), 120),
                "reason": clean(ban.get("reason", ""), 500),
                "date": clean(ban.get("date", ban.get("created_at", ban.get("time", ""))), 100),
                "banned_by": clean(ban.get("banned_by", ""), 100),
            }
        )
    return normalized, "", status


public_server_cache_lock = threading.RLock()
public_server_cache: dict[str, Any] = {
    "fetched_at": 0.0,
    "updated_at": "",
    "servers": None,
}
public_server_history: dict[str, list[dict[str, Any]]] = {}
public_server_aggregate_history: list[dict[str, Any]] = []


def _public_server_int(value: Any, field: str) -> int:
    if isinstance(value, bool):
        raise ValueError(f"Champ numérique invalide : {field}.")
    try:
        parsed = int(value)
    except (TypeError, ValueError, OverflowError) as exc:
        raise ValueError(f"Champ numérique invalide : {field}.") from exc
    if isinstance(value, float) and not value.is_integer():
        raise ValueError(f"Champ numérique invalide : {field}.")
    return parsed


def _normalize_public_server(row: Any, updated_at: str) -> dict[str, Any]:
    if not isinstance(row, dict):
        raise ValueError("Une entrée de l'annuaire n'est pas un objet JSON.")
    required_text = ("name", "terrain-name", "ip", "version")
    if any(not isinstance(row.get(key, ""), str) for key in required_text):
        raise ValueError("L'annuaire contient des champs texte invalides.")

    name = clean(row.get("name"), 200)
    terrain = clean(row.get("terrain-name"), 200)
    address = clean(row.get("ip"), 120)
    version = clean(row.get("version"), 80)
    if not name or not terrain or not address:
        raise ValueError("L'annuaire ne fournit pas le nom, le terrain ou l'adresse.")

    port = _public_server_int(row.get("port"), "port")
    players = _public_server_int(row.get("current-users"), "current-users")
    capacity = _public_server_int(row.get("max-clients"), "max-clients")
    if not 1 <= port <= 65535 or players < 0 or capacity < 1 or players > capacity:
        raise ValueError("L'annuaire fournit un port ou un compteur invalide.")

    return {
        "id": f"{address}:{port}",
        "name": name,
        "terrain": terrain,
        "players": players,
        "capacity": capacity,
        "version": version,
        "address": address,
        "port": port,
        "status": "online",
        "ping_ms": None,
        "player_names": None,
        "has_password": bool(row.get("has-password", False)),
        "official": bool(row.get("is-official", False)),
        "updated_at": updated_at,
    }


def _record_public_server_history(
    servers: list[dict[str, Any]], updated_at: str, timestamp: float
) -> None:
    cutoff = timestamp - PUBLIC_SERVER_HISTORY_TTL
    with public_server_cache_lock:
        for history in public_server_history.values():
            history[:] = [
                point for point in history if point["timestamp"] >= cutoff
            ][-PUBLIC_SERVER_HISTORY_MAX_POINTS:]
        for server in servers:
            history = public_server_history.setdefault(server["id"], [])
            history.append(
                {
                    "timestamp": timestamp,
                    "time": updated_at,
                    "players": server["players"],
                    "capacity": server["capacity"],
                }
            )
            if len(history) > PUBLIC_SERVER_HISTORY_MAX_POINTS:
                del history[:-PUBLIC_SERVER_HISTORY_MAX_POINTS]

        public_server_aggregate_history.append(
            {
                "timestamp": timestamp,
                "time": updated_at,
                "players": sum(server["players"] for server in servers),
                "capacity": sum(server["capacity"] for server in servers),
                "servers": len(servers),
            }
        )
        public_server_aggregate_history[:] = [
            point for point in public_server_aggregate_history
            if point["timestamp"] >= cutoff
        ][-PUBLIC_SERVER_HISTORY_MAX_POINTS:]

        if len(public_server_history) > 1000:
            active_ids = {server["id"] for server in servers}
            stale_ids = [
                server_id
                for server_id, history in public_server_history.items()
                if server_id not in active_ids
                and (not history or history[-1]["timestamp"] < cutoff)
            ]
            for server_id in stale_ids:
                public_server_history.pop(server_id, None)
            if len(public_server_history) > 1000:
                oldest = sorted(
                    public_server_history,
                    key=lambda server_id: public_server_history[server_id][-1]["timestamp"]
                    if public_server_history[server_id]
                    else 0,
                )
                for server_id in oldest[: len(public_server_history) - 1000]:
                    public_server_history.pop(server_id, None)


def public_servers_snapshot(force_refresh: bool = False) -> dict[str, Any]:
    now_monotonic = time.monotonic()
    with public_server_cache_lock:
        cached_servers = public_server_cache["servers"]
        fetched_at = float(public_server_cache["fetched_at"])
        age = now_monotonic - fetched_at if fetched_at else float("inf")
        if (
            not force_refresh
            and cached_servers is not None
            and age < PUBLIC_SERVERLIST_CACHE_TTL
        ):
            servers = [dict(server) for server in cached_servers]
            for server in servers:
                server["history"] = list(public_server_history.get(server["id"], []))
            return {
                "servers": servers,
                "aggregate_history": list(public_server_aggregate_history),
                "updated_at": public_server_cache["updated_at"],
                "cached": True,
                "stale": False,
                "error": None,
            }

        try:
            response = requests.get(
                PUBLIC_SERVERLIST_URL,
                headers={
                    "Accept": "application/json",
                    "User-Agent": f"{APP_NAME}/{APP_VERSION}",
                },
                timeout=(1.5, PUBLIC_SERVERLIST_TIMEOUT),
            )
            response.raise_for_status()
            payload = response.json()
            if not isinstance(payload, list):
                raise ValueError("La réponse de l'annuaire n'est pas un tableau JSON.")
            updated_at = now()
            servers = [_normalize_public_server(row, updated_at) for row in payload]
            timestamp = time.time()
            _record_public_server_history(servers, updated_at, timestamp)
            public_server_cache.update(
                {
                    "fetched_at": time.monotonic(),
                    "updated_at": updated_at,
                    "servers": servers,
                }
            )
            servers_with_history = [dict(server) for server in servers]
            for server in servers_with_history:
                server["history"] = list(public_server_history.get(server["id"], []))
            return {
                "servers": servers_with_history,
                "aggregate_history": list(public_server_aggregate_history),
                "updated_at": updated_at,
                "cached": False,
                "stale": False,
                "error": None,
            }
        except (requests.exceptions.RequestException, ValueError, TypeError) as exc:
            message = clean(exc, 500) or "Annuaire public indisponible."
            if ROR_API_TOKEN:
                message = message.replace(ROR_API_TOKEN, "[masqué]")
            still_usable = cached_servers is not None and age <= PUBLIC_SERVER_HISTORY_TTL
            stale_servers = [dict(server) for server in cached_servers] if still_usable else []
            for server in stale_servers:
                server["history"] = list(public_server_history.get(server["id"], []))
            return {
                "servers": stale_servers,
                "aggregate_history": list(public_server_aggregate_history),
                "updated_at": public_server_cache["updated_at"] if still_usable else "",
                "cached": still_usable,
                "stale": still_usable,
                "error": message,
            }


# ============================================================================
# STOCKAGE LOGS
# ============================================================================


@dataclass
class Player:
    uid: str = ""
    name: str = ""
    token: str = ""
    ip: str = ""
    version: str = ""
    language: str = ""
    slot: str = ""
    online: bool = True
    first_seen: str = ""
    last_seen: str = ""
    last_chat: str = ""


@dataclass
class TokenRecord:
    timestamp: str
    name: str
    token: str
    ip: str
    version: str
    language: str


class Store:
    def __init__(self) -> None:
        self.lock = threading.RLock()
        self.players: dict[str, Player] = {}
        self.tokens: dict[str, TokenRecord] = {}
        self.chat: list[dict[str, str]] = []
        self.logs: list[str] = []

    def clear_runtime(self) -> None:
        with self.lock:
            self.players.clear()
            self.tokens.clear()
            self.chat.clear()
            self.logs.clear()

    def add_log(self, line: str) -> None:
        with self.lock:
            self.logs.append(line)
            if len(self.logs) > MAX_LOG_LINES:
                del self.logs[:-MAX_LOG_LINES]

    def add_connection(
        self,
        timestamp: str,
        name: str,
        token: str,
        ip: str,
        version: str,
        language: str,
    ) -> None:
        token = normalize_token(token)
        name = clean(name, 100)
        key = token or "name:" + name.lower()
        player = self.players.get(key)
        if player is None:
            player = Player(
                name=name,
                token=token,
                ip=ip,
                version=version,
                language=language,
                online=True,
                first_seen=timestamp,
                last_seen=timestamp,
            )
            self.players[key] = player
        else:
            player.name = name or player.name
            player.token = token or player.token
            player.ip = ip or player.ip
            player.version = version or player.version
            player.language = language or player.language
            player.online = True
            player.last_seen = timestamp

        if token:
            self.tokens[token] = TokenRecord(timestamp, name, token, ip, version, language)
            while len(self.tokens) > MAX_TOKENS:
                oldest = next(iter(self.tokens), None)
                if oldest is None:
                    break
                self.tokens.pop(oldest, None)

    def associate_uid(self, uid: str, name: str, slot: str = "") -> None:
        uid = clean(uid, 30)
        name = clean(name, 100)
        if not uid:
            return

        old_key = None
        for key, player in self.players.items():
            if name and player.name.lower() == name.lower() and not player.uid:
                old_key = key
                break

        if old_key is not None:
            player = self.players.pop(old_key)
            player.uid = uid
            player.slot = slot or player.slot
            player.online = True
            player.last_seen = now()
            self.players[uid] = player
            return

        player = self.players.get(uid)
        if player is None:
            self.players[uid] = Player(
                uid=uid,
                name=name,
                slot=slot,
                online=True,
                first_seen=now(),
                last_seen=now(),
            )
        else:
            player.name = name or player.name
            player.slot = slot or player.slot
            player.online = True
            player.last_seen = now()

    def add_chat(self, timestamp: str, name: str, message: str) -> None:
        item = {
            "time": timestamp,
            "name": clean(name, 100),
            "message": clean(message, 1000),
        }
        if not item["message"]:
            return
        self.chat.append(item)
        if len(self.chat) > MAX_CHAT:
            del self.chat[:-MAX_CHAT]
        for player in self.players.values():
            if player.name.lower() == item["name"].lower():
                player.last_chat = item["message"]
                player.last_seen = timestamp

    def snapshot(self) -> dict[str, Any]:
        with self.lock:
            players = [asdict(p) for p in self.players.values() if p.online]
            players.sort(key=lambda p: p["name"].lower())
            all_players = [asdict(p) for p in self.players.values()]
            all_players.sort(key=lambda p: (not p["online"], p["name"].lower()))
            tokens = [asdict(t) for t in self.tokens.values()]
            tokens.sort(key=lambda t: t["name"].lower())
            return {
                "players": players,
                "all_players": all_players,
                "tokens": tokens,
                "chat": list(self.chat[-MAX_CHAT:]),
                "logs": list(self.logs[-MAX_LOG_LINES:]),
            }


store = Store()


# ============================================================================
# PARSEUR DE LOG
# ============================================================================

DATE_RE = re.compile(r"^(\d{2}-\d{2}-\d{4}\s+\d{2}:\d{2}:\d{2})")
CONNECTION_RE = re.compile(
    r"(?P<date>\d{2}-\d{2}-\d{4})\s+(?P<time>\d{2}:\d{2}:\d{2})"
    r".*?New\s+client:\s*(?P<name>.*?)\s*\((?P<language>[^)]*)\)"
    r".*?with\s+IP\s+(?P<ip>[0-9A-Fa-f:.]+)"
    r".*?using\s+RoR\s+(?P<version>[0-9.]+)"
    r".*?with\s+token\s+(?P<token>[A-Za-z0-9@._:-]+)",
    re.I,
)
CHAT_RE = re.compile(
    r"(?P<date>\d{2}-\d{2}-\d{4})\s+(?P<time>\d{2}:\d{2}:\d{2})"
    r".*?\|\s*INFO\s*\|\s*CHAT\s*\|\s*"
    r"(?P<name>[^:|]+):\s*(?P<message>.*)$",
    re.I,
)
SLOT_RE = re.compile(
    r"\*\s*(?P<uid>-?\d+)\s+(?P<name>.*?)\s*\(\s*slot\s+(?P<slot>\d+)\)",
    re.I,
)


def parse_line(line: str, live: bool = True) -> None:
    line = line.rstrip("\r\n")
    if not line:
        return

    match_date = DATE_RE.match(line)
    timestamp = match_date.group(1) if match_date else now()

    store.add_log(line)

    with store.lock:
        match = CONNECTION_RE.search(line)
        if match:
            name = clean(match.group("name"), 100)
            token = normalize_token(match.group("token"))
            ip = clean(match.group("ip"), 120)
            version = clean(match.group("version"), 50)
            language = clean(match.group("language"), 50)
            store.add_connection(timestamp, name, token, ip, version, language)
            if live:
                emit_event(
                    "CONNECTION",
                    f"{name} connecté",
                    {"name": name, "token": token, "ip": ip, "version": version, "language": language},
                )
            return

        match = CHAT_RE.search(line)
        if match:
            name = clean(match.group("name"), 100)
            message = clean(match.group("message"), 1000)
            if message:
                store.add_chat(timestamp, name, message)
                if live:
                    emit_event("CHAT", f"{name}: {message}", {"name": name, "message": message})
            return

        match = SLOT_RE.search(line)
        if match:
            uid = clean(match.group("uid"), 30)
            name = clean(match.group("name"), 100)
            slot = clean(match.group("slot"), 20)
            store.associate_uid(uid, name, slot)
            if live:
                emit_event("UID", f"{name} → UID {uid}", {"uid": uid, "name": name, "slot": slot})


class LogWatcher:
    def __init__(self) -> None:
        self.stop_event = threading.Event()
        self.thread: threading.Thread | None = None
        self.path: Path | None = None
        self.offset = 0
        self.initialized = False
        self.lock = threading.RLock()

    def start(self) -> None:
        with self.lock:
            if self.thread and self.thread.is_alive():
                return
            self.stop_event.clear()
            self.thread = threading.Thread(target=self.run, name="RoR-LogWatcher", daemon=True)
            self.thread.start()

    def stop(self) -> None:
        self.stop_event.set()

    def initialize(self, path: Path) -> None:
        if not path.exists():
            return
        try:
            store.clear_runtime()
            text = safe_read(path)
            lines = text.splitlines()
            for line in lines[-MAX_LOG_LINES:]:
                parse_line(line, live=False)
            self.offset = path.stat().st_size
            self.initialized = True
        except Exception as exc:
            emit_event("ERROR", f"Initialisation du log : {clean(exc, 500)}")

    def run(self) -> None:
        emit_event("SYSTEM", "Surveillance du log active.")
        while not self.stop_event.is_set():
            try:
                current_path = runtime_paths()["log"]
                if current_path != self.path:
                    self.path = current_path
                    self.offset = 0
                    self.initialized = False

                if not current_path.exists():
                    self.stop_event.wait(LOG_POLL)
                    continue

                size = current_path.stat().st_size
                if size < self.offset:
                    self.offset = 0
                    self.initialized = False

                if not self.initialized:
                    self.initialize(current_path)
                elif size > self.offset:
                    with current_path.open("r", encoding="utf-8", errors="replace") as file:
                        file.seek(self.offset)
                        data = file.read()
                        self.offset = file.tell()
                    for line in data.splitlines():
                        parse_line(line, live=True)

            except Exception as exc:
                emit_event("ERROR", f"Log watcher : {clean(exc, 500)}")

            self.stop_event.wait(LOG_POLL)


log_watcher = LogWatcher()


