# CONTROLE PROCESSUS ROR — ROBUSTE + ANTI DOUBLE INSTANCE
# ============================================================================


class ServerController:
    def __init__(self) -> None:
        self.process: subprocess.Popen | None = None
        self.external_pid: int | None = None
        self.start_time: float | None = None
        self.lock = threading.RLock()
        self.action_lock = threading.RLock()

    def candidates(self) -> list[Path]:
        names = ["rorserver.exe", "RoRServer.exe"] if platform.system() == "Windows" else ["rorserver", "RoRServer"]
        result: list[Path] = []
        configured = os.environ.get("ROR_SERVER_EXE", "").strip()
        if configured:
            try:
                result.append(Path(configured).expanduser().resolve())
            except Exception:
                pass
        result.extend(SERVER_ROOT / name for name in names)
        return result

    def find_executable(self) -> Path | None:
        for candidate in self.candidates():
            try:
                if candidate.is_file():
                    return candidate
            except Exception:
                continue
        return None

    def _same_server_process(self, proc: Any) -> bool:
        try:
            if proc.pid == os.getpid():
                return False

            name = (proc.info.get("name") or "").lower()
            if name not in {"rorserver.exe", "rorserver"}:
                return False

            exe = proc.info.get("exe")
            if exe:
                try:
                    if Path(exe).resolve() in {p.resolve() for p in self.candidates()}:
                        return True
                except Exception:
                    pass

            cwd = proc.info.get("cwd")
            if cwd:
                try:
                    return Path(cwd).resolve() == SERVER_ROOT
                except Exception:
                    pass

            cmdline = proc.info.get("cmdline") or []
            text = " ".join(str(x) for x in cmdline).lower()
            return "rorserver" in text and str(SERVER_ROOT).lower() in text
        except Exception:
            return False

    def _find_external_pid(self) -> int | None:
        if not psutil:
            return None
        try:
            for proc in psutil.process_iter(["pid", "name", "exe", "cwd", "cmdline"]):
                try:
                    if self._same_server_process(proc):
                        return int(proc.pid)
                except Exception:
                    continue
        except Exception:
            pass
        return None

    def _refresh_external_state(self) -> int | None:
        with self.lock:
            if self.process and self.process.poll() is None:
                self.external_pid = None
                return self.process.pid

            self.process = None
            pid = self._find_external_pid()
            self.external_pid = pid
            return pid

    def is_running(self) -> bool:
        with self.lock:
            if self.process:
                if self.process.poll() is None:
                    return True
                self.process = None
                self.start_time = None

            if self.external_pid:
                if psutil:
                    try:
                        if psutil.pid_exists(self.external_pid):
                            return True
                    except Exception:
                        pass
                self.external_pid = None

            return self._find_external_pid() is not None

    def running_pid(self) -> int | None:
        with self.lock:
            if self.process and self.process.poll() is None:
                return self.process.pid
            return self._refresh_external_state()

    def start(self) -> tuple[bool, str]:
        with self.action_lock:
            with self.lock:
                if self.is_running():
                    pid = self.running_pid()
                    return False, f"Le serveur est déjà démarré (PID {pid or '?'})."

                executable = self.find_executable()
                if executable is None:
                    return False, f"rorserver.exe introuvable dans : {SERVER_ROOT}"
                if not paths.cfg.exists():
                    return False, f"server.cfg introuvable : {paths.cfg}"

                flags = 0
                if platform.system() == "Windows":
                    flags = getattr(subprocess, "CREATE_NEW_PROCESS_GROUP", 0)

                command = [str(executable), "-c", str(paths.cfg), "-fg"]

                try:
                    process = subprocess.Popen(
                        command,
                        cwd=str(SERVER_ROOT),
                        stdin=subprocess.PIPE,
                        stdout=subprocess.PIPE,
                        stderr=subprocess.STDOUT,
                        text=True,
                        encoding="utf-8",
                        errors="replace",
                        bufsize=1,
                        creationflags=flags,
                    )
                except Exception as exc:
                    return False, f"Démarrage impossible : {clean(exc, 1000)}"

                self.process = process
                self.external_pid = None
                self.start_time = time.time()

                threading.Thread(
                    target=self._reader,
                    args=(process,),
                    name=f"RoR-Stdout-{process.pid}",
                    daemon=True,
                ).start()

                emit_event("SERVER", f"Serveur démarré : {executable.name} -c server.cfg -fg", {"pid": process.pid})
                return True, "Serveur RoR démarré."

    def _reader(self, process: subprocess.Popen) -> None:
        try:
            if process.stdout is not None:
                for line in process.stdout:
                    if line.strip():
                        parse_line(line, live=True)
        except Exception as exc:
            emit_event("ERROR", f"Lecture sortie serveur : {clean(exc, 500)}")
        finally:
            try:
                code = process.wait(timeout=0.2)
            except Exception:
                code = process.poll()

            with self.lock:
                if self.process is process:
                    self.process = None
                    self.start_time = None

            emit_event("SERVER", f"Processus RoR terminé (code {code}).", {"pid": process.pid, "exit_code": code})

    def send_command(self, command: str) -> tuple[bool, str]:
        command = clean(command, 2000)
        if not command:
            return False, "Commande vide."

        with self.action_lock:
            with self.lock:
                process = self.process
                if not process or process.poll() is not None:
                    return False, "Serveur arrêté ou console non contrôlée par ce panneau."
                if process.stdin is None:
                    return False, "Console indisponible."
                try:
                    process.stdin.write(command + "\n")
                    process.stdin.flush()
                    emit_event("CONSOLE", "> " + command)
                    return True, "Commande envoyée."
                except (BrokenPipeError, OSError) as exc:
                    return False, f"Échec console : {clean(exc, 500)}"
                except Exception as exc:
                    return False, f"Échec console : {clean(exc, 500)}"

    def stop(self) -> tuple[bool, str]:
        with self.action_lock:
            with self.lock:
                process = self.process
                if process and process.poll() is None:
                    try:
                        if platform.system() == "Windows":
                            try:
                                process.send_signal(signal.CTRL_BREAK_EVENT)
                            except Exception:
                                process.terminate()
                        else:
                            process.terminate()
                        emit_event("SERVER", "Arrêt du serveur demandé.", {"pid": process.pid})
                        return True, "Arrêt demandé."
                    except Exception as exc:
                        return False, f"Arrêt impossible : {clean(exc, 500)}"

                pid = self.external_pid or self._find_external_pid()
                if pid and psutil:
                    try:
                        proc = psutil.Process(pid)
                        proc.terminate()
                        self.external_pid = pid
                        emit_event("SERVER", "Arrêt du serveur externe demandé.", {"pid": pid})
                        return True, "Arrêt demandé."
                    except Exception as exc:
                        return False, f"Arrêt du processus externe impossible : {clean(exc, 500)}"

                return False, "Serveur déjà arrêté."

    def kill(self) -> tuple[bool, str]:
        killed = False
        killed_pids: list[int] = []

        with self.action_lock:
            with self.lock:
                process = self.process
                if process and process.poll() is None:
                    try:
                        process.kill()
                        killed = True
                        killed_pids.append(process.pid)
                    except Exception:
                        pass
                self.process = None
                self.start_time = None
                self.external_pid = None

            if psutil:
                try:
                    for proc in psutil.process_iter(["pid", "name", "exe", "cwd", "cmdline"]):
                        try:
                            if self._same_server_process(proc):
                                proc.kill()
                                killed = True
                                killed_pids.append(int(proc.pid))
                        except Exception:
                            continue
                except Exception:
                    pass

        if killed:
            emit_event("SERVER", "Processus RoR forcé à l’arrêt.", {"pids": sorted(set(killed_pids))})
            return True, "Processus RoR arrêté."
        return False, "Aucun processus RoR actif."

    def restart(self) -> tuple[bool, str]:
        with self.action_lock:
            if self.is_running():
                self.stop()
                deadline = time.time() + 10
                while self.is_running() and time.time() < deadline:
                    time.sleep(0.1)
                if self.is_running():
                    self.kill()
            return self.start()

    def uptime_seconds(self) -> int:
        with self.lock:
            if self.start_time is None or not self.process or self.process.poll() is not None:
                return 0
            return max(0, int(time.time() - self.start_time))


controller = ServerController()


