app = Flask(__name__)
app.config["JSON_AS_ASCII"] = False


@app.errorhandler(Exception)
def handle_unexpected_exception(exc):
    """Never drop an API connection because of an unhandled Flask exception."""
    emit_event("ERROR", f"Exception Flask : {clean(exc, 1200)}")
    if request.path.startswith("/api/"):
        return jsonify({"ok": False, "success": False, "error": "Erreur interne du panneau."}), 500
    return "Erreur interne du panneau.", 500


@app.before_request
def auth_guard():
    if not WEB_PASSWORD or request.path == "/health":
        return None

    # Header first. Query-string password is kept only for backwards
    # compatibility with the old panel and should not be used normally.
    supplied = request.headers.get("X-RoR-Admin-Password", "")
    if not supplied:
        supplied = request.args.get("password", "")
    if supplied == WEB_PASSWORD:
        return None

    return jsonify({"ok": False, "error": "Authentification requise."}), 401


