# GÉOLOCALISATION IP — CACHE ASYNCHRONE
# ============================================================================


def _ip_is_public(value: Any) -> bool:
    try:
        ip = ipaddress.ip_address(str(value).strip())
        return not (
            ip.is_private
            or ip.is_loopback
            or ip.is_reserved
            or ip.is_link_local
            or ip.is_multicast
            or ip.is_unspecified
        )
    except ValueError:
        return False


def _geo_lookup_worker(ip: str) -> None:
    try:
        response = requests.get(
            GEO_API_TEMPLATE.format(ip=ip),
            headers={"User-Agent": f"{APP_NAME}/{APP_VERSION}"},
            timeout=(1.5, 3.5),
        )
        if response.status_code != 200:
            raise RuntimeError(f"HTTP {response.status_code}")
        data = response.json()
        lat = float(data.get("latitude"))
        lon = float(data.get("longitude"))
        if not (-90 <= lat <= 90 and -180 <= lon <= 180):
            raise ValueError("Coordonnées invalides")
        result = {
            "ready": True,
            "ok": True,
            "lat": lat,
            "lon": lon,
            "city": clean(data.get("city", ""), 100),
            "region": clean(data.get("region", ""), 100),
            "country": clean(data.get("country_name", data.get("country", "")), 100),
            "country_code": clean(data.get("country_code", ""), 8).upper(),
            "org": clean(data.get("org", ""), 160),
            "updated": time.time(),
        }
        ttl = GEO_TTL
    except Exception as exc:
        result = {
            "ready": True,
            "ok": False,
            "error": clean(exc, 300),
            "updated": time.time(),
        }
        ttl = GEO_NEGATIVE_TTL

    with geo_lock:
        geo_cache[ip] = {**result, "expires": time.time() + ttl}
        geo_pending.discard(ip)


def geolocation_for_ip(ip: str) -> dict[str, Any]:
    ip = str(ip or "").strip()
    if not _ip_is_public(ip):
        return {"ready": True, "ok": False, "private": True, "label": "Réseau local"}

    now_ts = time.time()
    with geo_lock:
        cached = geo_cache.get(ip)
        if cached and float(cached.get("expires", 0)) > now_ts:
            return dict(cached)
        if ip not in geo_pending:
            geo_pending.add(ip)
            try:
                geo_executor.submit(_geo_lookup_worker, ip)
            except Exception:
                geo_pending.discard(ip)
    return {"ready": False, "ok": False, "pending": True}


@app.get("/api/player-locations")
def api_player_locations():
    players, error, http_status = api_players_data()
    if error:
        return jsonify({
            "ok": False,
            "error": error,
            "players": [],
            "locations": [],
            "count": 0,
            "http_status": http_status,
        })

    locations: list[dict[str, Any]] = []
    for player in players:
        ip = clean(player.get("ip", ""), 120)
        geo = geolocation_for_ip(ip)
        locations.append({
            "id": player.get("id", ""),
            "name": player.get("name", "Joueur inconnu"),
            "ip": ip,
            "streams": int(player.get("streams", 0) or 0),
            **geo,
        })

    return jsonify({
        "ok": True,
        "count": len(locations),
        "locations": locations,
        "generated_at": now(),
    })


