@app.get("/action/<action>")
def server_action(action: str):
    action = action.lower().strip()
    if action == "start":
        ok, message = controller.start()
    elif action == "stop":
        ok, message = controller.stop()
    elif action == "restart":
        ok, message = controller.restart()
    elif action == "kill":
        ok, message = controller.kill()
    else:
        ok, message = False, "Action inconnue."

    emit_event("SERVER", message)
    return redirect(url_for("dashboard"))


