@app.post("/api/admin/announce")
def api_announce():
    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        return jsonify({"ok": False, "error": "JSON invalide ou absent."}), 400

    message = data.get("message")
    if not isinstance(message, str) or not message.strip():
        return jsonify({"ok": False, "error": "Le message d'annonce ne peut pas être vide."}), 400
    message = message.strip()
    if len(message.encode("utf-8")) > 1000:
        return jsonify({"ok": False, "error": "Le message dépasse la limite de 1000 octets UTF-8."}), 400

    has_player_id = "player_id" in data
    has_player_ids = "player_ids" in data
    if has_player_id and has_player_ids:
        return jsonify({"ok": False, "error": "Utilise player_id ou player_ids, pas les deux."}), 400

    payload: dict[str, Any] = {"message": message}
    if has_player_id:
        player_id = parse_api_id(data["player_id"])
        if player_id is None:
            return jsonify({"ok": False, "error": "player_id doit être un entier positif ou nul."}), 400
        payload["player_id"] = player_id
    elif has_player_ids:
        raw_ids = data["player_ids"]
        if not isinstance(raw_ids, list) or not 1 <= len(raw_ids) <= 64:
            return jsonify({"ok": False, "error": "player_ids doit contenir de 1 à 64 IDs."}), 400
        player_ids = [parse_api_id(item) for item in raw_ids]
        if any(player_id is None for player_id in player_ids):
            return jsonify({"ok": False, "error": "Chaque ID de player_ids doit être un entier positif ou nul."}), 400
        payload["player_ids"] = player_ids

    result = call_ror_admin_api("/api/v1/admin/announce", payload)
    if _result_success(result):
        emit_event("ADMIN", "Annonce envoyée via l'API RoR.", payload)
        return jsonify({"ok": True, "success": True, "message": _result_message(result, "Annonce envoyée.")})

    message = _result_message(result, "L'API RoR a refusé l'annonce.")
    emit_event("ERROR", f"Annonce refusée : {message}")
    return jsonify({"ok": False, "success": False, "error": message}), upstream_error_status(result)


@app.post("/api/admin/teleport")
def api_teleport():
    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        return jsonify({"ok": False, "error": "JSON invalide ou absent."}), 400

    player_id = parse_api_id(data.get("player_id"))
    if player_id is None:
        return jsonify({"ok": False, "error": "player_id doit être un entier positif ou nul."}), 400

    has_destination_player = "destination_player_id" in data
    coordinate_keys = ("x", "y", "z")
    has_coordinates = any(key in data for key in coordinate_keys)
    if has_destination_player == has_coordinates:
        return jsonify({
            "ok": False,
            "error": "Indique destination_player_id ou les trois coordonnées x, y et z.",
        }), 400

    payload: dict[str, Any] = {"player_id": player_id}
    if has_destination_player:
        destination_id = parse_api_id(data["destination_player_id"])
        if destination_id is None:
            return jsonify({"ok": False, "error": "destination_player_id doit être un entier positif ou nul."}), 400
        payload["destination_player_id"] = destination_id
    else:
        if not all(key in data for key in coordinate_keys):
            return jsonify({"ok": False, "error": "Les coordonnées x, y et z doivent être fournies ensemble."}), 400
        coordinates: dict[str, float] = {}
        for key in coordinate_keys:
            value = data[key]
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                return jsonify({"ok": False, "error": f"La coordonnée {key} doit être un nombre fini."}), 400
            try:
                coordinate = float(value)
            except (OverflowError, ValueError):
                return jsonify({"ok": False, "error": f"La coordonnée {key} doit être un nombre fini."}), 400
            if not math.isfinite(coordinate):
                return jsonify({"ok": False, "error": f"La coordonnée {key} doit être un nombre fini."}), 400
            coordinates[key] = coordinate
        payload.update(coordinates)

    result = call_ror_admin_api("/api/v1/admin/teleport", payload)
    if _result_success(result):
        emit_event("MODERATION", f"Téléportation mise en file pour player_id {player_id}.", payload)
        return jsonify({
            "ok": True,
            "success": True,
            "message": _result_message(result, "Commande de téléportation mise en file."),
            "queued": True,
            "player_id": player_id,
        })

    message = _result_message(result, "L'API RoR a refusé la téléportation.")
    emit_event("ERROR", f"Téléportation refusée : {message}", payload)
    return jsonify({"ok": False, "success": False, "error": message}), upstream_error_status(result)


