@app.post("/api/bans/unban")
def api_unban():
    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        return jsonify({"ok": False, "error": "JSON invalide ou absent."}), 400
    raw_ban_id = data.get("ban_id", "")
    ban_id_text = str(raw_ban_id).strip()
    if isinstance(raw_ban_id, bool) or not re.fullmatch(r"\d{1,20}", ban_id_text):
        return jsonify({"ok": False, "error": "ID de bannissement manquant ou invalide."}), 400
    ban_id = int(ban_id_text)

    result = call_ror_admin_api("/api/v1/admin/unban", {"ban_id": ban_id})
    success = isinstance(result, dict) and _result_success(result)
    if success:
        emit_event("MODERATION", f"Débannissement réussi → ban_id {ban_id}", {"ban_id": ban_id})
        return jsonify({"ok": True, "success": True, "message": _result_message(result, "Joueur débanni."), "ban_id": ban_id})

    message = _result_message(result, "Le serveur a refusé le débannissement.")
    status = int(result.get("_http_status", 502)) if isinstance(result, dict) else 502
    emit_event("ERROR", f"Débannissement refusé → ban_id {ban_id} : {message}", {"ban_id": ban_id, "http_status": status})
    return jsonify({"ok": False, "success": False, "error": message, "ban_id": ban_id}), upstream_error_status(result)


