@app.get("/api/maps")
def api_maps():
    maps = discover_maps()
    map_root = next((item.get("_asset_root") for item in maps if item.get("_asset_root")), str(runtime_paths()["resources"]))
    for map_item in maps:
        map_item["preview_url"] = (
            url_for("map_preview", relative_path=map_item["preview"])
            if map_item["preview"]
            else ""
        )
        map_item.pop("_asset_root", None)
        map_item.pop("_config_resdir", None)
    return jsonify({
        "ok": True,
        "count": len(maps),
        "maps": maps,
        "resource_dir": map_root,
        "configured_terrain": cfg_value("terrain", "any"),
    })


@app.get("/maps/preview/<path:relative_path>")
def map_preview(relative_path: str):
    map_item = next((item for item in discover_maps() if item["preview"] == relative_path), None)
    if map_item is None:
        abort(404)
    asset_root = Path(map_item.get("_asset_root", runtime_paths()["resources"])).resolve()
    preview = map_path_under(asset_root, relative_path)
    if preview is None:
        abort(404)
    if preview.suffix.lower() not in MAP_PREVIEW_EXTENSIONS or not preview.is_file():
        abort(404)
    return send_file(preview, conditional=True)


@app.post("/api/maps/apply")
def api_apply_map():
    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        return jsonify({"ok": False, "error": "JSON invalide ou absent."}), 400
    map_id = clean(data.get("id", ""), 500)
    map_item = next((item for item in discover_maps() if item["id"] == map_id), None)
    if map_item is None:
        return jsonify({"ok": False, "error": "Cette map n’est pas installée dans le répertoire de ressources."}), 404

    config_text = safe_read(paths.cfg)
    lines = config_text.splitlines()

    def update_setting(key: str, value: str) -> None:
        setting = re.compile(rf"^(\s*{re.escape(key)}\s*=\s*).*$", re.I)
        for index, line in enumerate(lines):
            if line.lstrip().startswith(("#", ";")):
                continue
            match = setting.match(line)
            if match:
                lines[index] = match.group(1) + value
                return
        lines.append(f"{key} = {value}")

    update_setting("terrain", map_item["config_value"])
    config_resdir = map_item.get("_config_resdir", "")
    if config_resdir:
        update_setting("resdir", config_resdir)

    updated_config = "\n".join(lines).rstrip("\n") + "\n"
    backup = backup_file(paths.cfg)
    if not safe_write(paths.cfg, updated_config):
        return jsonify({"ok": False, "error": "Impossible d’écrire server.cfg."}), 500

    emit_event("CONFIG", f"Terrain configuré : {map_item['config_value']}", {"map": map_id, "resdir": config_resdir, "backup": str(backup) if backup else ""})
    message = f"Terrain configuré sur « {map_item['name']} ». Redémarre le serveur pour appliquer le changement."
    if config_resdir:
        message = f"Terrain configuré sur « {map_item['name']} » et resdir réglé sur « {config_resdir} ». Redémarre le serveur."
    return jsonify({
        "ok": True,
        "success": True,
        "message": message,
        "terrain": map_item["config_value"],
        "resdir": config_resdir,
        "backup": str(backup) if backup else "",
    })


