@app.post("/api/player/action")
def api_player_action():
    """Validate and proxy player moderation actions to the native RoR API."""
    try:
        data = request.get_json(silent=True)
        if not isinstance(data, dict):
            return jsonify({"ok": False, "success": False, "error": "JSON invalide ou absent."}), 400

        raw_uid = data.get("player_id", data.get("uid", ""))
        player_id = parse_api_id(raw_uid)
        name = clean(data.get("name", ""), 100)
        action = str(data.get("action", "")).strip().lower()
        reason = clean(data.get("reason", ""), 1000)

        if player_id is None:
            emit_event("ERROR", "Action joueur refusée : Player ID invalide.")
            return jsonify({"ok": False, "success": False, "error": "Player ID invalide."}), 400
        if action not in {"kick", "ban", "freeze", "unfreeze", "message"}:
            return jsonify({"ok": False, "success": False, "error": "Action inconnue."}), 400

        if action == "message":
            if not reason:
                return jsonify({"ok": False, "success": False, "error": "Message vide."}), 400
            endpoint = "/api/v1/admin/announce"
            payload: dict[str, Any] = {"player_id": player_id, "message": reason}
        elif action in {"kick", "ban"}:
            endpoint = f"/api/v1/admin/{action}"
            payload = {
                "player_id": player_id,
                "reason": reason or ("Expulsion administrative" if action == "kick" else "Bannissement administratif"),
            }
        else:
            endpoint = f"/api/v1/admin/{action}"
            payload = {"player_id": player_id}

        emit_event(
            "MODERATION",
            f"{action.upper()} demandé → player_id {player_id}",
            {"player_id": player_id, "name": name, "transport": "api"},
        )
        result = call_ror_admin_api(endpoint, payload)
        if _result_success(result):
            message = _result_message(result, "Message envoyé." if action == "message" else f"{action.capitalize()} effectué.")
            emit_event(
                "MODERATION",
                f"{action.upper()} accepté par l'API → player_id {player_id}",
                {"player_id": player_id, "name": name, "transport": "api"},
            )
            return jsonify({
                "ok": True,
                "success": True,
                "message": message,
                "player_id": player_id,
                "transport": "api",
            })

        message = _result_message(result, f"L'API RoR a refusé l'action {action}.")
        emit_event("ERROR", f"{action.upper()} refusé → player_id {player_id} : {message}")
        return jsonify({
            "ok": False,
            "success": False,
            "error": message,
            "player_id": player_id,
            "transport": "api",
        }), upstream_error_status(result)

    except Exception as exc:
        emit_event("ERROR", f"Exception /api/player/action : {clean(exc, 1000)}")
        return jsonify({"ok": False, "success": False, "error": "Erreur interne du panneau pendant l'action joueur."}), 500


