@app.post("/api/say")
def api_say():
    data = request.get_json(silent=True) or {}
    message = data.get("message", "")
    if not isinstance(message, str) or not message.strip():
        return jsonify({"ok": False, "error": "Message vide."}), 400
    message = message.strip()
    if len(message.encode("utf-8")) > 1000:
        return jsonify({"ok": False, "error": "Le message dépasse la limite de 1000 octets UTF-8."}), 400
    result = call_ror_admin_api("/api/v1/admin/announce", {"message": message})
    if _result_success(result):
        emit_event("ADMIN", "Message global envoyé via l'API RoR.")
        return jsonify({"ok": True, "success": True, "message": _result_message(result, "Annonce envoyée.")})
    error = _result_message(result, "L'API RoR a refusé l'annonce.")
    return jsonify({"ok": False, "success": False, "error": error}), upstream_error_status(result)


