@app.get("/mods")
def mods_page():
    root = runtime_paths()["resources"]
    items: list[tuple[str, str, str]] = []

    if root.exists():
        try:
            for item in sorted(root.iterdir(), key=lambda p: p.name.lower()):
                try:
                    if item.is_file():
                        size = item.stat().st_size
                    else:
                        size = sum(child.stat().st_size for child in item.rglob("*") if child.is_file())
                    modified = datetime.fromtimestamp(item.stat().st_mtime).strftime("%Y-%m-%d %H:%M")
                    items.append((item.name, human_bytes(size), modified))
                except Exception:
                    continue
        except Exception:
            pass

    rows = "".join(
        f"<tr><td class='mono'>{esc(name)}</td><td>{esc(size)}</td><td>{esc(modified)}</td></tr>"
        for name, size, modified in items
    ) or '<tr><td colspan="3" class="empty">Aucune ressource.</td></tr>'

    content = f"""
<section class="card"><div class="card-head"><div><h2 class="card-title">📦 Ressources</h2><div class="card-note mono">{esc(root)}</div></div><button class="btn" onclick="location.reload()">↻</button></div>
<div class="table-wrap"><table class="table"><thead><tr><th>Nom</th><th>Taille</th><th>Modification</th></tr></thead><tbody>{rows}</tbody></table></div>
</section>
"""
    return render("mods", "Ressources", content)


# ============================================================================
# BACKUPS
# ============================================================================


@app.get("/backups")
def backups_page():
    items: list[tuple[str, str, str]] = []

    if paths.backups.exists():
        try:
            directories = [path for path in paths.backups.iterdir() if path.is_dir()]
            for directory in sorted(directories, key=lambda p: p.name, reverse=True):
                try:
                    size = sum(child.stat().st_size for child in directory.rglob("*") if child.is_file())
                    modified = datetime.fromtimestamp(directory.stat().st_mtime).strftime("%Y-%m-%d %H:%M")
                    items.append((directory.name, human_bytes(size), modified))
                except Exception:
                    continue
        except Exception:
            pass

    rows = "".join(
        f"<tr><td class='mono'>{esc(name)}</td><td>{esc(size)}</td><td>{esc(modified)}</td></tr>"
        for name, size, modified in items
    ) or '<tr><td colspan="3" class="empty">Aucune sauvegarde.</td></tr>'

    content = f"""
<section class="card"><div class="card-head"><div><h2 class="card-title">💾 Backups</h2><div class="card-note mono">{esc(paths.backups)}</div></div><button class="btn" onclick="location.reload()">↻</button></div>
<div class="table-wrap"><table class="table"><thead><tr><th>Dossier</th><th>Taille</th><th>Date</th></tr></thead><tbody>{rows}</tbody></table></div>
</section>
"""
    return render("backups", "Backups", content)


# ============================================================================
# SSE
# ============================================================================


@app.get("/api/events")
def api_events():
    subscriber: queue.Queue = queue.Queue(maxsize=120)
    with events_lock:
        event_subscribers.append(subscriber)
        backlog = list(events[-30:])

    def stream():
        try:
            for item in backlog:
                yield "data: " + json.dumps(item, ensure_ascii=False) + "\n\n"
            while True:
                try:
                    item = subscriber.get(timeout=20)
                    yield "data: " + json.dumps(item, ensure_ascii=False) + "\n\n"
                except queue.Empty:
                    yield ": keepalive\n\n"
        finally:
            with events_lock:
                try:
                    event_subscribers.remove(subscriber)
                except ValueError:
                    pass

    return Response(
        stream(),
        mimetype="text/event-stream",
        headers={
            "Cache-Control": "no-cache, no-transform",
            "X-Accel-Buffering": "no",
            "Connection": "keep-alive",
        },
    )


