def shutdown() -> None:
    try:
        geo_executor.shutdown(wait=False, cancel_futures=True)
    except Exception:
        pass
    try:
        log_watcher.stop()
    except Exception:
        pass
    try:
        if controller.is_running():
            controller.stop()
    except Exception:
        pass


atexit.register(shutdown)


